// outputs kF[32], vF[32] same indexing for y.
void F_tv(const int kT[32], const uint8_t vT[32], int kF[32], uint8_t vF[32]){
    // extract per byte known/val as arrays [4][8]
    int kx[4][8]; uint8_t vx[4][8];
