    int ky2[8]; uint8_t vy2[8];
    for(int j=0;j<8;j++){ int sidx=(j-2+8)%8; ky2[j]=ks1[sidx]; vy2[j]=vs1[sidx]; }
    // s2 = x3 + y2
    int ks2[8]; uint8_t vs2[8];
    add8(kx[3],vx[3],ky2,vy2,1,0,ks2,vs2);
    int ky3[8]; uint8_t vy3[8];
    for(int j=0;j<8;j++){ int sidx=(j-2+8)%8; ky3[j]=ks2[sidx]; vy3[j]=vs2[sidx]; }
