    int ks3[8]; uint8_t vs3[8];
    add8(kq,vq,ky2,vy2,1,0,ks3,vs3);
    int ky1[8]; uint8_t vy1[8];
    for(int j=0;j<8;j++){ int sidx=(j-2+8)%8; ky1[j]=ks3[sidx]; vy1[j]=vs3[sidx]; }
    // s4 = x0 + y1 +1
    int ks4[8]; uint8_t vs4[8];
    add8(kx[0],vx[0],ky1,vy1,1,1,ks4,vs4);
    int ky0[8]; uint8_t vy0[8];
    for(int j=0;j<8;j++){ int sidx=(j-2+8)%8; ky0[j]=ks4[sidx]; vy0[j]=vs4[sidx]; }
