int check_partial(uint32_t s_low[4], int k){
    // compute K known flags/values (32 bits each)
    int kK[4][32]; uint8_t vK[4][32];
    for(int r=0;r<4;r++){
        uint32_t Klow = expand_trunc(s_low[r], k);
        for(int j=0;j<32;j++){
            if(j<k){ kK[r][j]=1; vK[r][j]=(Klow>>j)&1; }
            else { kK[r][j]=0; vK[r][j]=0; }
        }
    }
    // for each pair, simulate
    for(int pi=0; pi<nPairs; pi++){
        uint32_t PL = getleft(P[pi]);
        uint32_t PR = getright(P[pi]);
        uint32_t CH = getleft(C[pi]); // note merge(right,left): high=right=R4, low=left=L4^R4
        uint32_t CL = getright(C[pi]);
